# Test helper for host/tests/tls_test.cpp: a TLS-terminating TCP proxy (like the reverse proxy in
# front of a relay). Usage: tls_proxy.py CERT KEY BACKEND_PORT PORT_FILE
# Listens on 127.0.0.1 (any free port, written to PORT_FILE), terminates TLS with CERT/KEY and pipes
# the plaintext to 127.0.0.1:BACKEND_PORT. Certificates are generated by the test in its temp dir.
import os
import socket
import ssl
import sys
import threading


def pipe(a, b):
    try:
        while True:
            d = a.recv(65536)
            if not d:
                break
            b.sendall(d)
    except OSError:
        pass
    for s in (a, b):
        try:
            s.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass


def main():
    cert, key, backend, port_file = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4]
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    ctx.load_cert_chain(cert, key)
    ls = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    ls.bind(("127.0.0.1", 0))
    ls.listen(16)
    tmp = port_file + ".tmp"
    with open(tmp, "w") as f:
        f.write(str(ls.getsockname()[1]))
    os.replace(tmp, port_file)
    while True:
        c, _ = ls.accept()
        try:
            t = ctx.wrap_socket(c, server_side=True)
        except (ssl.SSLError, OSError):
            c.close()  # the client refused our certificate: exactly what the tests expect
            continue
        b = socket.create_connection(("127.0.0.1", backend))
        threading.Thread(target=pipe, args=(t, b), daemon=True).start()
        threading.Thread(target=pipe, args=(b, t), daemon=True).start()


if __name__ == "__main__":
    main()
